await import('./server-r4.js');
process.env.PORT=String(PUBLIC_PORT);

function clean(v){return String(v==null?'':v).trim();}
function b64url(buf){return Buffer.from(buf).toString('base64url');}
function safeEq(a,b){const x=Buffer.from(clean(a)),y=Buffer.from(clean(b));return x.length===y.length&&timingSafeEqual(x,y);}
function managerSessionPayload(email,role,exp){return['v1','MANAGER_SESSION',clean(email).toLowerCase(),clean(role),String(exp)].join('\n');}
function auditorPortalSessionPayload(email,role,exp){return['v1','AUDITOR_PORTAL_SESSION',clean(email).toLowerCase(),clean(role),String(exp)].join('\n');}
function auditorPlanningSessionPayload(email,role,auditId,exp){return['v1','AUDITOR_PLANNING_SESSION',clean(email).toLowerCase(),clean(role),clean(auditId),String(exp)].join('\n');}
function signManagerSessionHandoff(payload){return b64url(createHmac('sha256',WRITE_KEY).update(payload).digest());}
function signSession(payload){return createHmac('sha256',SESSION_SECRET).update(payload).digest('base64url');}
function sha256b64url(v){return createHash('sha256').update(String(v||''),'utf8').digest('base64url');}
function configMarker(){return sha256b64url(WRITE_KEY).slice(0,10);}
function planningOpenPayload(email,role,auditId,exp){return['v1',clean(email).toLowerCase(),clean(role),clean(auditId),String(exp)].join('\n');}
function planningCommitPayload(email,role,auditId,exp,planningPayloadJson){return['v2','PLANNING_COMMIT',clean(email).toLowerCase(),clean(role),clean(auditId),String(exp),sha256b64url(planningPayloadJson)].join('\n');}
function signPlanningCommit(payload){return b64url(createHmac('sha256',WRITE_KEY).update(payload).digest());}
function issueSession(identity,ttlSeconds=SESSION_TTL_SECONDS){
  if(SESSION_SECRET.length<32)throw new Error('SESSION_SECRET_NOT_CONFIGURED');
  const ttl=Math.max(300,Math.floor(Number(ttlSeconds)||SESSION_TTL_SECONDS)),now=Math.floor(Date.now()/1000);
  const payload=b64url(JSON.stringify({v:1,email:clean(identity.email).toLowerCase(),role:clean(identity.role),iat:now,exp:now+ttl}));
  return payload+'.'+signSession(payload);
}
function sessionCookie(token,maxAge=SESSION_TTL_SECONDS){return SESSION_COOKIE+'='+token+'; Max-Age='+Math.max(300,Math.floor(Number(maxAge)||SESSION_TTL_SECONDS))+'; Path=/; HttpOnly; Secure; SameSite=Lax';}

function clearSessionCookie(){return SESSION_COOKIE+'=; Max-Age=0; Path=/; HttpOnly; Secure; SameSite=Lax';}
function portalLoginHtml(){
  const dev=RUNTIME_ENV==='DEV',managerReady=!!DEV_MANAGER_EMAIL,auditorReady=!!DEV_AUDITOR_EMAIL;
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AMS - Login</title><style>
  *{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:linear-gradient(135deg,#0f172a,#1f2937 55%,#334155);font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#111827;padding:24px}.card{width:min(520px,100%);background:white;border-radius:18px;padding:28px;box-shadow:0 24px 80px rgba(15,23,42,.35)}h1{margin:0 0 6px;font-size:24px}.sub{color:#64748b;font-size:13px;margin-bottom:22px}.env{display:inline-block;font-size:11px;font-weight:800;padding:3px 7px;border-radius:999px;background:#dbeafe;color:#1d4ed8;margin-bottom:18px}.actions{display:grid;gap:10px}.login{width:100%;padding:12px 14px;border:1px solid #cbd5e1;border-radius:10px;background:#f8fafc;font-weight:750;font-size:15px;cursor:pointer}.login.primary{background:#2563eb;border-color:#2563eb;color:white}.login:disabled{opacity:.45;cursor:not-allowed}.note{margin-top:18px;color:#64748b;font-size:12px;line-height:1.45}.err{margin-top:14px;padding:10px;border-radius:8px;background:#fee2e2;color:#991b1b;font-size:12px}</style></head><body><main class="card"><div class="env">${dev?'DEV':'SECURE'}</div><h1>Audit Management System</h1><div class="sub">Agri Quality Assurance · Portal 2.0</div>${dev?`<div class="actions"><form method="post" action="/auth/dev-login"><input type="hidden" name="role" value="Manager"><button class="login primary" type="submit" ${managerReady?'':'disabled'}>Login as Manager</button></form><form method="post" action="/auth/dev-login"><input type="hidden" name="role" value="Auditor"><button class="login" type="submit" ${auditorReady?'':'disabled'}>Login as Auditor</button></form></div>${(!managerReady||!auditorReady)?'<div class="err">DEV login identities are not configured on this Cloud Run service.</div>':''}<div class="note">DEV shortcut login creates a short-lived Portal 2.0 session directly in Cloud Run. No Apps Script page is used.</div>`:`<div class="err">Production OTP login is not exposed on this DEV service.</div>`}</main></body></html>`;
}

function sendJson(res,status,body,headers={}){res.writeHead(status,{'content-type':'application/json; charset=utf-8','cache-control':'no-store',...headers});res.end(JSON.stringify(body));}
function sendHtml(res,status,body,headers={}){res.writeHead(status,{'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff','referrer-policy':'no-referrer',...headers});res.end(body);}
async function readRaw(req,max=32768){let raw='';for await(const chunk of req){raw+=chunk;if(raw.length>max)throw new Error('REQUEST_TOO_LARGE');}return raw;}
async function readForm(req){return new URLSearchParams(await readRaw(req,16384));}
function devIdentityForRole(role){
  const r=clean(role).toLowerCase();
  if(RUNTIME_ENV!=='DEV')return null;
  if(r==='manager'&&DEV_MANAGER_EMAIL)return{email:DEV_MANAGER_EMAIL,role:'Manager'};
  if(r==='auditor'&&DEV_AUDITOR_EMAIL)return{email:DEV_AUDITOR_EMAIL,role:'Auditor'};
  return null;
}
async function handleDevLogin(req,res){
  if(RUNTIME_ENV!=='DEV')return sendJson(res,404,{ok:false,error:'NOT_FOUND'});
  const form=await readForm(req),identity=devIdentityForRole(form.get('role'));
  if(!identity)return sendJson(res,403,{ok:false,error:'DEV_LOGIN_ROLE_NOT_CONFIGURED'});
  if(SESSION_SECRET.length<32)return sendJson(res,500,{ok:false,error:'SESSION_SECRET_NOT_CONFIGURED'});
  const devTtl=2*60*60,token=issueSession(identity,devTtl);
  res.writeHead(303,{'set-cookie':sessionCookie(token,devTtl),'location':'/','cache-control':'no-store','referrer-policy':'no-referrer'});
  return res.end();
}

function verifyManagerSessionHandoff(form){
  if(WRITE_KEY.length<32)return{ok:false,error:'WRITE_BRIDGE_NOT_CONFIGURED'};
  const email=clean(form.get('email')).toLowerCase(),role=clean(form.get('role')),auditId=clean(form.get('auditId')),exp=Number(clean(form.get('exp'))),supplied=clean(form.get('signature'));
  if(!email||!role||!exp||!supplied)return{ok:false,error:'HANDOFF_REQUIRED_FIELDS_MISSING'};
  const roleKey=role.toLowerCase();if(roleKey!=='manager'&&roleKey!=='auditor')return{ok:false,error:'ROLE_FORBIDDEN'};
  const now=Date.now();
  if(exp<now-MANAGER_HANDOFF_CLOCK_SKEW_MS)return{ok:false,error:'HANDOFF_EXPIRED'};
  if(exp>now+MANAGER_HANDOFF_MAX_FUTURE_MS)return{ok:false,error:'HANDOFF_EXPIRY_INVALID'};
  const payload=roleKey==='manager'
    ? managerSessionPayload(email,'Manager',exp)
    : (auditId?auditorPlanningSessionPayload(email,'Auditor',auditId,exp):auditorPortalSessionPayload(email,'Auditor',exp));
  const expected=signManagerSessionHandoff(payload);
  if(!safeEq(supplied,expected))return{ok:false,error:'HANDOFF_SIGNATURE_INVALID'};
  if(roleKey==='manager')return{ok:true,email,role:'Manager',location:'/'};
  return auditId?{ok:true,email,role:'Auditor',auditId,location:'/planning?auditId='+encodeURIComponent(auditId)}:{ok:true,email,role:'Auditor',location:'/'};
}
async function handleManagerSessionHandoff(req,res){
  let form;try{form=await readForm(req);}catch(err){return sendJson(res,413,{ok:false,error:clean(err&&err.message||err)});}
  const verified=verifyManagerSessionHandoff(form);if(!verified.ok)return sendJson(res,401,verified);
  if(SESSION_SECRET.length<32)return sendJson(res,500,{ok:false,error:'SESSION_SECRET_NOT_CONFIGURED'});
  const token=issueSession(verified);res.writeHead(303,{'set-cookie':sessionCookie(token),'location':verified.location||'/','cache-control':'no-store','referrer-policy':'no-referrer'});return res.end();
}
async function sessionIdentity(req){
  const r=await fetch('http://127.0.0.1:'+INNER_PORT+'/api/v1/session',{method:'GET',headers:{cookie:clean(req.headers.cookie)},redirect:'manual'});
  let body={};try{body=await r.json();}catch{}
  if(!r.ok||!body||body.ok!==true||!body.identity)return null;return body.identity;
}
function validPlanningBody(body){
  const auditId=clean(body?.auditId),auditorEmail=clean(body?.auditorEmail).toLowerCase(),blocks=Array.isArray(body?.blocks)?body.blocks:[];
  if(!auditId||!auditorEmail||!blocks.length)return{ok:false,error:'PLANNING_REQUIRED_FIELDS_MISSING'};
  for(const b of blocks){
    const date=clean(b?.date),start=clean(b?.start),end=clean(b?.end);
    if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!/^\d{2}:\d{2}$/.test(start)||!/^\d{2}:\d{2}$/.test(end)||end<=start)return{ok:false,error:'PLANNING_BLOCK_INVALID'};
  }
  return{ok:true,auditId,auditorEmail,blocks};
}
function planningCommitForm(identity,body){
  const chk=validPlanningBody(body);if(!chk.ok)return{ok:false,error:chk.error};
  if(!GAS_WRITE_URL||WRITE_KEY.length<32)return{ok:false,error:'WRITE_BRIDGE_NOT_CONFIGURED'};
  const planningPayloadJson=JSON.stringify({auditorEmail:chk.auditorEmail,auditorName:clean(body?.auditorName),blocks:chk.blocks.map(b=>({date:clean(b.date),start:clean(b.start),end:clean(b.end),execLoc:clean(b.execLoc||b.location||'HQ')||'HQ',slotComment:clean(b.slotComment||b.comment)})),comment:clean(body?.comment)});
  const email=clean(identity.email).toLowerCase(),role='Manager',exp=Date.now()+60000;
  const signature=signPlanningCommit(planningCommitPayload(email,role,chk.auditId,exp,planningPayloadJson));
  return{ok:true,action:GAS_WRITE_URL,fields:{action:'externalplanningworkspace',mode:'commit',email,role,auditId:chk.auditId,exp:String(exp),planningPayload:planningPayloadJson,signature}};
}
async function handlePlanningCommitHandoff(req,res){
  const identity=await sessionIdentity(req);if(!identity)return sendJson(res,401,{ok:false,error:'SESSION_REQUIRED'});
  if(!['manager','auditor'].includes(clean(identity.role).toLowerCase()))return sendJson(res,403,{ok:false,error:'ROLE_FORBIDDEN'});
  let body={};try{body=JSON.parse(await readRaw(req,65536)||'{}');}catch{return sendJson(res,400,{ok:false,error:'BAD_JSON'});}
  const chk=validPlanningBody(body);if(!chk.ok)return sendJson(res,400,{ok:false,error:chk.error});
  const started=Date.now();
  try{
    const r=await fetch('http://127.0.0.1:'+INNER_PORT+'/api/v1/planning/direct-commit',{method:'POST',headers:{'content-type':'application/json',cookie:SESSION_COOKIE+'='+issueSession(identity)},body:JSON.stringify(body)}),out=await r.json();
    if(!r.ok||!out||out.success!==true)return sendJson(res,r.status||409,{ok:false,error:out?.error||'DIRECT_COMMIT_BLOCKED',detail:out?.detail||out?.message||out?.error||'DIRECT_COMMIT_EMPTY',result:out||{success:false,error:'DIRECT_COMMIT_EMPTY'},bridgeRoundTripMs:Date.now()-started,configMarker:configMarker(),writeOwner:'CLOUD_RUN_DIRECT_SHEETS_MANAGER_PLAN'});
    return sendJson(res,200,{ok:true,result:out,gasRoundTripMs:0,verifyMs:0,bridgeRoundTripMs:Date.now()-started,configMarker:configMarker(),writeOwner:'CLOUD_RUN_DIRECT_SHEETS_MANAGER_PLAN'});
  }catch(err){return sendJson(res,502,{ok:false,error:'PLANNING_DIRECT_COMMIT_FAILED',detail:clean(err&&err.message||err),bridgeRoundTripMs:Date.now()-started});}
}
const ROTATION_CACHE_TTL_MS=5*60*1000;
const rotationReadCache=new Map(),rotationReadInflight=new Map();
function rotationCacheKey(auditId,auditorEmail){return clean(auditId)+'|'+clean(auditorEmail).toLowerCase()}
async function canonicalRotationReadUncached(identity,auditId,auditorEmail){const started=Date.now(),u=new URL('http://127.0.0.1:'+INNER_PORT+'/api/v1/planning/rotation-direct');u.searchParams.set('auditId',clean(auditId));u.searchParams.set('auditorEmail',clean(auditorEmail).toLowerCase());const r=await fetch(u,{method:'GET',headers:{cookie:SESSION_COOKIE+'='+issueSession(identity)},redirect:'manual'}),raw=await r.text();let out;try{out=JSON.parse(raw)}catch{throw new Error('ROTATION_DIRECT_NON_JSON_'+r.status)}if(!r.ok||out.success===false)throw new Error(out.detail||out.message||out.error||('ROTATION_DIRECT_HTTP_'+r.status));out.__bridgeTiming={fetchMs:Date.now()-started,bodyMs:0,totalMs:Date.now()-started};return out;}
async function canonicalRotationRead(identity,auditId,auditorEmail){
  const key=rotationCacheKey(auditId,auditorEmail),now=Date.now(),hit=rotationReadCache.get(key);
  if(hit&&hit.expiresAt>now)return {...hit.value,__rotationCache:'HIT'};
  if(hit)rotationReadCache.delete(key);
  if(rotationReadInflight.has(key))return rotationReadInflight.get(key);
  const pending=canonicalRotationReadUncached(identity,auditId,auditorEmail).then(out=>{
    if(out&&out.success!==false)rotationReadCache.set(key,{value:out,expiresAt:Date.now()+ROTATION_CACHE_TTL_MS});
    return {...out,__rotationCache:'MISS'};
  }).finally(()=>rotationReadInflight.delete(key));
  rotationReadInflight.set(key,pending);
  return pending;
}
async function handlePlanningRotation(req,res,u){const identity=await sessionIdentity(req);if(!identity)return sendJson(res,401,{ok:false,error:'SESSION_REQUIRED'});if(!['manager','auditor'].includes(clean(identity.role).toLowerCase()))return sendJson(res,403,{ok:false,error:'ROLE_FORBIDDEN'});const auditId=clean(u.searchParams.get('auditId')),auditorEmail=clean(u.searchParams.get('auditorEmail')).toLowerCase();if(!auditId||!auditorEmail)return sendJson(res,400,{ok:false,error:'ROTATION_REQUIRED_FIELDS_MISSING'});if(clean(identity.role).toLowerCase()==='auditor'&&auditorEmail!==clean(identity.email).toLowerCase())return sendJson(res,403,{ok:false,error:'AUDITOR_CANNOT_CHECK_OTHER_AUDITOR'});try{const out=await canonicalRotationRead(identity,auditId,auditorEmail);return sendJson(res,out&&out.success===false?409:200,out);}catch(err){return sendJson(res,500,{ok:false,error:'ROTATION_READ_BRIDGE_FAILED',detail:clean(err&&err.message||err)});}}
